const out = [];
for (const item of $input.all()) {
  const bin = item.binary || {};
  for (const key of Object.keys(bin)) {
    const b = bin[key];
    const name = b.fileName || key;
    const ext = String(b.fileExtension || name.split('.').pop() || '').toLowerCase();
    let typ = 'unbekannt';
    if (ext === 'pdf') typ = 'pdf';
    else if (ext === 'docx') typ = 'docx';
    else if (['png', 'jpg', 'jpeg', 'webp', 'heic', 'tif', 'tiff'].includes(ext)) typ = 'bild';
    out.push({ json: { datei_name: name, datei_typ: typ }, binary: { data: b } });
  }
}
return out;

return $input.all().map((item) => {
  const j = item.json || {};
  let text = j.text || j.content || j.xml || '';
  if (Array.isArray(text)) text = text.join('\n');
  if (text && typeof text === 'object') text = JSON.stringify(text);
  let name = j.datei_name;
  let typ = j.datei_typ;
  if (!name) {
    try {
      const src = $('Dateien aufteilen').item.json;
      name = src.datei_name;
      typ = src.datei_typ;
    } catch (e) {}
  }
  return {
    json: {
      datei_name: name || 'unbekannt',
      datei_typ: typ || 'unbekannt',
      text: String(text).slice(0, 20000),
    },
  };
});

const out = [];
for (const item of $input.all()) {
  const bin = item.binary || {};
  const keys = Object.keys(bin);
  const key = keys.find((k) => String(bin[k].fileName || '').toLowerCase() === 'document.xml');
  if (!key) continue;
  out.push({ json: item.json || {}, binary: { data: bin[key] } });
}
return out;

return $input.all().map((item) => {
  const xml = String(item.json.xml || '');
  const text = xml
    .replace(/<\/w:p>/g, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/\n{2,}/g, '\n')
    .trim();
  return {
    json: {
      datei_name: item.json.datei_name,
      datei_typ: item.json.datei_typ,
      text: text,
    },
  };
});

