// Punkt 3: Werte prüfen und vereinheitlichen – ein Item pro Angebot
const toNumber = (v) => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return isNaN(v) ? null : v;
  let s = String(v).replace(/[^0-9,.-]/g, '');
  if (s.includes(',') && s.includes('.')) {
    s = s.lastIndexOf(',') > s.lastIndexOf('.') ? s.replace(/\./g, '').replace(/,/g, '.') : s.replace(/,/g, '');
  } else if (s.includes(',')) {
    s = s.replace(/\./g, '').replace(/,/g, '.');
  }
  const n = parseFloat(s);
  return isNaN(n) ? null : n;
};
const clean = (v) => (v === null || v === undefined ? '' : String(v).trim());
const list = (v) => (Array.isArray(v) ? v.map(clean).filter(Boolean) : clean(v) ? [clean(v)] : []);
const round2 = (n) => (n === null ? null : Math.round(n * 100) / 100);

return $input.all().map((item, i) => {
  const o = item.json.output || {};
  let datei_name = 'unbekannt', datei_typ = 'unbekannt';
  try {
    const src = $('Text vereinheitlichen').all()[i].json;
    datei_name = src.datei_name || datei_name;
    datei_typ = src.datei_typ || datei_typ;
  } catch (e) {}

  const positionen = (Array.isArray(o.positionen) ? o.positionen : []).map((p) => ({
    bezeichnung_original: clean(p.bezeichnung_original),
    kategorie: clean(p.kategorie) || 'Sonstige Leistung',
    menge: toNumber(p.menge),
    einheit: clean(p.einheit),
    einzelpreis: toNumber(p.einzelpreis),
    gesamtpreis: toNumber(p.gesamtpreis),
  }));

  let netto = toNumber(o.netto_summe);
  let mwst = toNumber(o.mwst_betrag);
  let brutto = toNumber(o.brutto_summe);
  if (brutto === null && netto !== null && mwst !== null) brutto = round2(netto + mwst);
  let gesamt = toNumber(o.gesamtpreis);
  if (gesamt === null) gesamt = brutto !== null ? brutto : netto;

  // Plausibilitätsprüfung: Summe der Positionen vs. Netto- bzw. Gesamtsumme
  const summePos = round2(positionen.reduce((s, p) => s + (p.gesamtpreis || 0), 0));
  const pruefhinweise = [];
  if (positionen.length > 1 && summePos > 0) {
    const vergleich = netto !== null ? netto : gesamt;
    if (vergleich !== null && Math.abs(summePos - vergleich) > 1) {
      pruefhinweise.push(`Positionssumme ${summePos} weicht von Summe ${vergleich} ab`);
    }
  }

  const fehlend = [];
  if (!clean(o.anbieter)) fehlend.push('Anbieter');
  if (gesamt === null) fehlend.push('Gesamtpreis');
  if (!clean(o.angebotsdatum)) fehlend.push('Angebotsdatum');
  if (!clean(o.ausfuehrungszeitraum)) fehlend.push('Ausführungszeitraum');
  if (!clean(o.projekt)) fehlend.push('Projekt');

  return {
    json: {
      angebot_id: `A${String(i + 1).padStart(2, '0')}`,
      datei_name,
      datei_typ,
      anbieter: clean(o.anbieter),
      angebotsnummer: clean(o.angebotsnummer),
      angebotsdatum: clean(o.angebotsdatum),
      gueltig_bis: clean(o.gueltig_bis),
      projekt: clean(o.projekt) || 'ohne Projektangabe',
      gewerk: clean(o.gewerk) || 'Sonstiges',
      leistungsumfang: clean(o.leistungsumfang),
      positionen,
      anzahl_positionen: positionen.length,
      netto_summe: netto,
      mwst_betrag: mwst,
      brutto_summe: brutto,
      gesamtpreis: gesamt,
      preisbasis: clean(o.preisbasis) || 'unklar',
      preisart: clean(o.preisart) || 'pauschal',
      waehrung: clean(o.waehrung) || 'EUR',
      ausfuehrungszeitraum: clean(o.ausfuehrungszeitraum),
      dauer_wochen_min: toNumber(o.dauer_wochen_min),
      dauer_wochen_max: toNumber(o.dauer_wochen_max),
      enthalten: list(o.enthalten),
      ausschluesse: list(o.ausschluesse),
      zusatzkosten_risiken: list(o.zusatzkosten_risiken),
      sonstige_hinweise: clean(o.sonstige_hinweise),
      fehlende_angaben: fehlend,
      pruefhinweise,
      datenstatus: fehlend.length || pruefhinweise.length ? 'prüfen' : 'vollständig',
    },
  };
});

// Punkt 5a: Eine Zeile pro Position – für den Leistungsvergleich über Anbieter hinweg
const auswertung_id = $execution.id;
const out = [];
for (const item of $input.all()) {
  const a = item.json;
  const pos = a.positionen.length ? a.positionen : [{ bezeichnung_original: '(keine Positionen erkennbar)', kategorie: 'Sonstige Leistung' }];
  pos.forEach((p, idx) => {
    out.push({
      json: {
        auswertung_id,
        angebot_id: a.angebot_id,
        projekt: a.projekt,
        gewerk: a.gewerk,
        anbieter: a.anbieter,
        pos_nr: idx + 1,
        kategorie: p.kategorie,
        bezeichnung_original: p.bezeichnung_original,
        menge: p.menge ?? '',
        einheit: p.einheit ?? '',
        einzelpreis: p.einzelpreis ?? '',
        positionspreis: p.gesamtpreis ?? '',
        preisart: a.preisart,
        datei_name: a.datei_name,
      },
    });
  });
}
return out;

// Punkt 4 (Vorbereitung): Angebote je Projekt + Gewerk gruppieren und Kennzahlen
// regelbasiert berechnen. Die KI bekommt fertige Zahlen -> nachvollziehbar, keine Rechenfehler.
const groups = {};
for (const item of $input.all()) {
  const a = item.json;
  const key = `${a.projekt} | ${a.gewerk}`;
  (groups[key] = groups[key] || { projekt: a.projekt, gewerk: a.gewerk, angebote: [] }).angebote.push(a);
}

const median = (arr) => {
  const s = [...arr].sort((x, y) => x - y);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};
const r2 = (n) => Math.round(n * 100) / 100;

return Object.values(groups).map((g) => {
  const preise = g.angebote.map((a) => a.gesamtpreis).filter((p) => typeof p === 'number');
  const med = preise.length ? median(preise) : null;
  const kennzahlen = {
    anzahl_angebote: g.angebote.length,
    anzahl_mit_preis: preise.length,
    preis_min: preise.length ? Math.min(...preise) : null,
    preis_max: preise.length ? Math.max(...preise) : null,
    preis_median: med,
    preis_durchschnitt: preise.length ? r2(preise.reduce((s, p) => s + p, 0) / preise.length) : null,
  };

  const angebote = g.angebote.map((a) => {
    const abw = med && typeof a.gesamtpreis === 'number' ? r2(((a.gesamtpreis - med) / med) * 100) : null;
    const flags = [];
    if (abw !== null && preise.length >= 3 && abw <= -15) flags.push(`Preis ${abw}% unter Median – ungewöhnlich niedrig, Leistungsumfang prüfen`);
    if (abw !== null && preise.length >= 3 && abw >= 15) flags.push(`Preis ${abw}% über Median`);
    if (a.preisart === 'circa') flags.push('nur Circa-Preis');
    if (a.preisart === 'nach_aufwand') flags.push('Abrechnung nach Aufwand – Kosten offen');
    if (a.preisbasis === 'unklar') flags.push('netto/brutto nicht angegeben');
    if (a.ausschluesse.length) flags.push('Ausschlüsse: ' + a.ausschluesse.join(', '));
    if (a.zusatzkosten_risiken.length) flags.push('Kostenrisiken: ' + a.zusatzkosten_risiken.join(', '));
    if (a.fehlende_angaben.length) flags.push('Fehlt: ' + a.fehlende_angaben.join(', '));
    flags.push(...a.pruefhinweise);
    // Nur Geschäftsdaten an die Vergleichs-KI (Datenminimierung)
    return {
      angebot_id: a.angebot_id,
      anbieter: a.anbieter,
      angebotsdatum: a.angebotsdatum,
      leistungsumfang: a.leistungsumfang,
      kategorien: [...new Set(a.positionen.map((p) => p.kategorie))],
      gesamtpreis: a.gesamtpreis,
      preisbasis: a.preisbasis,
      preisart: a.preisart,
      abweichung_median_prozent: abw,
      ausfuehrungszeitraum: a.ausfuehrungszeitraum,
      dauer_wochen_min: a.dauer_wochen_min,
      dauer_wochen_max: a.dauer_wochen_max,
      enthalten: a.enthalten,
      ausschluesse: a.ausschluesse,
      zusatzkosten_risiken: a.zusatzkosten_risiken,
      auffaelligkeiten_regelbasiert: flags,
    };
  });

  return { json: { projekt: g.projekt, gewerk: g.gewerk, kennzahlen, angebote } };
});

