// Punkt 5b: Eine Zeile pro Angebot = extrahierte Daten + Kennzahlen + KI-Bewertung
const auswertung_id = $execution.id;
const erfasst_am = $now.toFormat('yyyy-MM-dd HH:mm');
const gruppen = $('Kennzahlen je Gewerk').all();
const alleAngebote = $('Werte normalisieren').all().map((x) => x.json);
const txt = (v) => (Array.isArray(v) ? v.join('; ') : v ?? '');

const out = [];
$input.all().forEach((item, i) => {
  const g = gruppen[i].json;
  const ki = item.json.output || {};
  const bew = Array.isArray(ki.bewertungen) ? ki.bewertungen : [];
  for (const k of g.angebote) {
    const a = alleAngebote.find((x) => x.angebot_id === k.angebot_id) || {};
    const b = bew.find((x) => x.angebot_id === k.angebot_id) || {};
    out.push({
      json: {
        auswertung_id,
        erfasst_am,
        projekt: g.projekt,
        gewerk: g.gewerk,
        angebot_id: k.angebot_id,
        anbieter: a.anbieter,
        angebotsdatum: a.angebotsdatum,
        datei_name: a.datei_name,
        leistungsumfang: a.leistungsumfang,
        gesamtpreis: a.gesamtpreis ?? '',
        waehrung: a.waehrung,
        preisbasis: a.preisbasis,
        preisart: a.preisart,
        abweichung_median_prozent: k.abweichung_median_prozent ?? '',
        ausfuehrungszeitraum: a.ausfuehrungszeitraum,
        enthalten: txt(a.enthalten),
        ausschluesse: txt(a.ausschluesse),
        zusatzkosten_risiken: txt(a.zusatzkosten_risiken),
        rang: b.rang ?? '',
        ki_einstufung: b.einstufung || 'nicht bewertet',
        staerken: txt(b.staerken),
        schwaechen: txt(b.schwaechen),
        auffaelligkeiten: txt([...(b.auffaelligkeiten || []), ...k.auffaelligkeiten_regelbasiert]),
        ki_begruendung: b.kurzbegruendung || '',
        datenstatus: a.datenstatus,
        fehlende_angaben: txt(a.fehlende_angaben),
      },
    });
  }
});
const key = (r) => `${r.json.projekt}|${r.json.gewerk}|${String(r.json.rang).padStart(3, '0')}`;
return out.sort((x, y) => key(x).localeCompare(key(y)));

// Punkt 5c: Bericht je Projekt + Gewerk (Kennzahlen, Zusammenfassung, Entscheidungsgrundlage)
const auswertung_id = $execution.id;
const erfasst_am = $now.toFormat('yyyy-MM-dd HH:mm');
const gruppen = $('Kennzahlen je Gewerk').all();
const eur = (n) => (typeof n === 'number' ? n.toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €' : '–');

return $input.all().map((item, i) => {
  const g = gruppen[i].json;
  const k = g.kennzahlen;
  const ki = item.json.output || {};
  const bew = (ki.bewertungen || []).slice().sort((a, b) => a.rang - b.rang);
  const guenstigstes = g.angebote.filter((a) => a.gesamtpreis === k.preis_min).map((a) => a.anbieter).join(', ');
  const abraten = bew.filter((b) => b.einstufung === 'abraten').map((b) => b.anbieter).join(', ');
  const ranking = bew.map((b) => `${b.rang}. ${b.anbieter} (${b.einstufung})`).join(' | ');
  const bericht = [
    `Projekt: ${g.projekt} – Gewerk: ${g.gewerk}`,
    `${k.anzahl_angebote} Angebot(e), Preisspanne ${eur(k.preis_min)} bis ${eur(k.preis_max)}, Median ${eur(k.preis_median)}.`,
    ki.zusammenfassung || '',
    `Empfehlung: ${ki.empfehlung_anbieter || '–'} – ${ki.empfehlung_begruendung || ''}`,
    abraten ? `Abzuraten: ${abraten}.` : '',
    `Ranking: ${ranking}`,
  ].filter(Boolean).join('\n');

  return {
    json: {
      auswertung_id,
      erfasst_am,
      projekt: g.projekt,
      gewerk: g.gewerk,
      anzahl_angebote: k.anzahl_angebote,
      preis_min: k.preis_min ?? '',
      preis_max: k.preis_max ?? '',
      preis_median: k.preis_median ?? '',
      preis_durchschnitt: k.preis_durchschnitt ?? '',
      guenstigster_anbieter: guenstigstes,
      empfohlener_anbieter: ki.empfehlung_anbieter || '',
      empfehlung_begruendung: ki.empfehlung_begruendung || '',
      abzuraten: abraten,
      ranking,
      bericht,
    },
  };
});
